/***********************************************************
 * UUPM design tokens — Data-Dense Dashboard
 * (Override via Format-pane fontFamily / color pickers.)
 ***********************************************************/
/***********************************************************
 * 1. Base Structure
 ***********************************************************/
.bfusion-root {
  width: 100%;
  height: 100%;
  position: relative;
  overflow: hidden;
  font-family: "Space Grotesk", "Inter", "Segoe UI", system-ui, sans-serif;
  color: #0F172A;
}
.bfusion-root *:focus-visible {
  outline: 2px solid #E8612A;
  outline-offset: 2px;
  border-radius: 2px;
}
@media (prefers-reduced-motion: reduce) {
  .bfusion-root *,
  .bfusion-root *::before,
  .bfusion-root *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }
}
/***********************************************************
 * Intro Splash Overlay — first-render branded animation.
 * Skip entirely under prefers-reduced-motion (gated in visual.ts).
 ***********************************************************/
@keyframes bfusion-intro-fade-in {
  from {
    opacity: 0;
    transform: translate3d(0, 8px, 0);
  }
  to {
    opacity: 1;
    transform: translate3d(0, 0, 0);
  }
}
@keyframes bfusion-intro-fade-out {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
@keyframes bfusion-intro-cell {
  from {
    opacity: 0;
    transform: translate3d(0, 4px, 0) scale(0.85);
  }
  to {
    opacity: 1;
    transform: translate3d(0, 0, 0) scale(1);
  }
}
@keyframes bfusion-intro-bar {
  from {
    transform: translateX(-100%);
  }
  to {
    transform: translateX(0);
  }
}
.bfusion-intro-splash {
  position: absolute;
  inset: 0;
  z-index: 50;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(180deg, #FFFFFF 0%, #F8FAFC 100%);
  cursor: pointer;
  animation: bfusion-intro-fade-in 220ms ease-out both;
  user-select: none;
}
.bfusion-intro-splash--leaving {
  animation: bfusion-intro-fade-out 280ms ease-in forwards;
  pointer-events: none;
}
.bfusion-intro-splash__inner {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 32px 40px;
  max-width: 360px;
  text-align: center;
  border-top: 3px solid #E8612A;
  background: #FFFFFF;
  border-radius: 6px;
  box-shadow: 0 8px 28px rgba(15, 23, 42, 0.08);
}
.bfusion-intro-splash__mark {
  width: 60px;
  height: 60px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 4px;
}
.bfusion-intro-splash__mark svg {
  display: block;
}
.bfusion-intro-splash__title {
  font-family: "Archivo", "Space Grotesk", "Inter", "Segoe UI", system-ui, sans-serif;
  font-size: 18px;
  font-weight: 700;
  color: #0F172A;
  line-height: 1.2;
  letter-spacing: 0.02em;
  animation: bfusion-intro-fade-in 320ms ease-out 540ms both;
}
.bfusion-intro-splash__tagline {
  font-family: "Space Grotesk", "Inter", "Segoe UI", system-ui, sans-serif;
  font-size: 12px;
  font-weight: 500;
  color: #475569;
  line-height: 1.5;
  margin-top: -4px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  animation: bfusion-intro-fade-in 320ms ease-out 680ms both;
}
.bfusion-intro-splash__bar {
  width: 140px;
  height: 2px;
  margin-top: 10px;
  background: #E2E8F0;
  border-radius: 2px;
  overflow: hidden;
}
.bfusion-intro-splash__bar-fill {
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, #E8612A 0%, #1F2A44 100%);
  transform: translateX(-100%);
  animation: bfusion-intro-bar 1200ms ease-out 200ms forwards;
}
.bfusion-landing-wrap {
  width: 100%;
  height: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #FFFFFF;
}
.bfusion-chart-wrap {
  width: 100%;
  height: 100%;
  overflow: hidden;
  position: relative;
}
.bfusion-empty {
  display: flex;
  width: 100%;
  height: 100%;
  align-items: center;
  justify-content: center;
  padding: 20px 24px 28px 24px;
  box-sizing: border-box;
}
.bfusion-empty__message {
  font-family: "Space Grotesk", "Inter", "Segoe UI", system-ui, sans-serif;
  font-size: 13px;
  color: #475569;
  font-weight: 500;
  text-align: center;
  letter-spacing: 0.2px;
}
/***********************************************************
 * 2. Landing Page
 ***********************************************************/
.bfusion-landing {
  display: flex;
  flex-direction: column;
  align-items: center;
  max-width: 420px;
  padding: 20px;
  box-sizing: border-box;
  font-family: "Space Grotesk", "Inter", "Segoe UI", system-ui, sans-serif;
  text-align: center;
}
.bfusion-landing__logo-container {
  width: 130px;
  height: 84px;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #FF5500;
  border-radius: 12px;
  box-shadow: 0 3px 8px rgba(0, 0, 0, 0.08);
  margin-bottom: 24px;
  overflow: hidden;
}
.bfusion-landing__logo {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.bfusion-landing__text-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
}
.bfusion-landing__title {
  font-family: "Archivo", "Space Grotesk", "Inter", "Segoe UI", system-ui, sans-serif;
  font-size: 16px;
  font-weight: 600;
  color: #0F172A;
  margin: 0 0 14px 0;
  padding: 0;
  line-height: 1.25;
}
.bfusion-landing__description {
  font-size: 12px;
  font-weight: 400;
  color: #475569;
  margin: 0;
  padding: 0;
  line-height: 1.6;
}
.bfusion-landing__description strong {
  font-weight: 600;
  color: #0F172A;
}
.bfusion-landing__separator {
  width: 60%;
  height: 1px;
  background-color: #EAEAEA;
  margin: 20px 0;
}
.bfusion-landing__metadata {
  font-size: 10.5px;
  color: #8C8C8C;
  margin-bottom: 4px;
  font-weight: 400;
}
.bfusion-landing__metadata a {
  color: #8C8C8C;
  text-decoration: none;
}
.bfusion-landing__metadata a:hover {
  text-decoration: underline;
}
/***********************************************************
 * 3. Insights Sidebar
 ***********************************************************/
.bfusion-sidebar::-webkit-scrollbar {
  width: 5px;
}
.bfusion-sidebar::-webkit-scrollbar-thumb {
  background: #d0d0d0;
  border-radius: 3px;
}
.bfusion-sidebar::-webkit-scrollbar-track {
  background: transparent;
}
/***********************************************************
 * 4. Tooltip
 ***********************************************************/
.bfusion-tooltip {
  line-height: 1.5;
  color: #333;
}
.bfusion-tooltip div {
  margin-bottom: 1px;
}
/***********************************************************
 * 5. Legend Bar
 ***********************************************************/
.bfusion-legend-bar {
  background: #fff;
  flex-wrap: wrap;
  user-select: none;
}
/* ========================================================================== */
/* License Badge & Watermark                                                   */
/* ========================================================================== */
.bfusion-license-badge-wrap {
  position: absolute;
  bottom: 4px;
  left: 8px;
  z-index: 20;
  pointer-events: none;
}
.bfusion-license-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 10px;
  border-radius: 4px;
  font-size: 9px;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  line-height: 1.3;
  pointer-events: auto;
  max-width: 380px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge--valid {
  background: rgba(5, 150, 105, 0.08);
  border: 1px solid rgba(5, 150, 105, 0.25);
  color: #059669;
}
.bfusion-license-badge--invalid {
  background: rgba(220, 38, 38, 0.06);
  border: 1px solid rgba(220, 38, 38, 0.2);
  color: #DC2626;
}
.bfusion-license-badge__icon {
  font-size: 11px;
  flex-shrink: 0;
}
.bfusion-license-badge__text {
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge__text strong {
  font-weight: 600;
}
.bfusion-watermark {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 15;
  pointer-events: none;
  display: flex;
  align-items: center;
  justify-content: center;
  background: repeating-linear-gradient(-45deg, transparent, transparent 120px, rgba(220, 38, 38, 0.03) 120px, rgba(220, 38, 38, 0.03) 122px);
}
.bfusion-watermark__content {
  text-align: center;
  opacity: 0.18;
  user-select: none;
  transform: rotate(-18deg);
}
.bfusion-watermark__title {
  font-size: 56px;
  font-weight: 900;
  color: #DC2626;
  letter-spacing: 12px;
  line-height: 1;
  font-family: "Segoe UI", sans-serif;
}
.bfusion-watermark__subtitle {
  font-size: 16px;
  font-weight: 600;
  color: #DC2626;
  margin-top: 6px;
  letter-spacing: 3px;
  text-transform: uppercase;
  font-family: "Segoe UI", sans-serif;
}
.bfusion-watermark__link {
  font-size: 11px;
  color: #9CA3AF;
  margin-top: 12px;
  font-family: "Segoe UI", sans-serif;
}
